-- 071: Sri Gur Sobha (Kavi Sainapati), Institute of Sikh Studies edition (2014), as a curator-only corpus.
--
-- See pipeline/gur-sobha/README.md. The typed text belongs to the edition, so the corpus is loaded
-- curator-only (source_rights, 069; corpora, 070) until permission to publish it is settled. Publishing
-- is one update, then re-run refresh_word_frequencies and refresh_word_corpus_stats, and refresh
-- word_writer_stats:
--   update source_rights set visibility = 'public', rights_status = 'permitted', licence = '…'
--    where code = 'gur_sobha_iss';
--
-- One row per tuk, as for Dasam Bani and Sarbloh; ang = the printed page. Shabad ids 920001-920483
-- (one per run of one chhand, or titled section, and per chapter), ours: no source publishes any. Ids
-- in use: SGGS 1-5540, Dasam 7402+, Bhai Gurdas 40001+, Sarbloh 900001-901559, Nand Lal 910061.
-- writer_id 9001 is ours too: BaniDB, whose writer ids the others use (47 Guru Gobind Singh Ji,
-- 48 Bhai Nand Lal Ji), has no Sainapati.
--
-- The lines themselves are loaded by `npm run build:gur-sobha` (its load SQL), not here.

insert into source_rights (code, visibility, rights_status, notes) values
  ('gur_sobha_iss', 'curator', 'pending',
   'Institute of Sikh Studies, Chandigarh (2014): the verse is public domain, the typed text and its readings are the edition''s')
on conflict (code) do nothing;

-- id 7 pinned: production's sequence has already handed out 7, so it would give 8,
-- while a fresh replay gives 7.
insert into sources (id, code, name, version, description, slug, kind, tier, rank, page_unit,
                     searched_by_default, author, external_refs)
values (
  7, 'gur_sobha_iss',
  'Sri Gur Sobha (Kavi Sainapati)',
  'iss-2014',
  'Sainapati''s Sri Gur Sobha (1701), 20 chapters, 935 verses, one row per tuk, as printed by the Institute of Sikh Studies, Chandigarh (2014, tr. Kulwant Singh), from its Asees text layer. Typing slips corrected; the edition''s verse numbers kept as printed. Curator-only until permission to publish is settled.',
  'gur-sobha', 'poetry', 'historical', 50, 'Page',
  false, 'Kavi Sainapati', '{}'::jsonb
)
on conflict (code) do nothing;
select setval('sources_id_seq', (select max(id) from sources));

insert into shabads (id, writer_english, writer_id, ang_start, source_fk)
select v.id, 'Kavi Sainapati', 9001, v.ang, (select id from sources where code = 'gur_sobha_iss')
